return {
  terrain: {
    hook: "activated", label: "Walk In",
    available: (H, actor) => H.resource.focusCount(actor) > 0,
    async run(H, actor, ctx) {
      await H.effects.apply([{ type: "claimTerrainTag", label: "Walk In Like You Own the Place" }], ctx);
      if (ctx._cancelled) return false;
      await H.resource.adjust(actor, { focus: -1 });
    },
  },
};
